-- Read-only predicate regression; synthetic grants, not a live RLS integration test.
WITH cases(name,expected,grant_present,phase,expired,foreign_requester,wrong_recipe,status) AS (VALUES ('authorized_claim',true,true,'preparing',false,false,false,'executing'),('missing_grant',false,false,'preparing',false,false,false,'executing'),('expired_lease',false,true,'preparing',true,false,false,'executing'),('wrong_scope',false,true,'preparing',false,true,false,'executing'),('wrong_recipe',false,true,'preparing',false,false,true,'executing'),('invalid_phase',false,true,'retryable',false,false,false,'executing'),('revoked_grant_quarantine',true,false,'quarantined',true,false,false,'reconciliation-required')), seeds AS (SELECT *, 'mission-coding-'||repeat('a',64) AS id, CASE WHEN foreign_requester THEN 'other' ELSE 'github:32674233' END AS requester, 'github:GLORIFIER7/GLORIFIER:comment:123' AS idempotency_key, 2 AS version, 'worker-1' AS lease_owner, statement_timestamp()+CASE WHEN expired THEN interval '-1 second' ELSE interval '4 minutes' END AS lease_expires_at FROM cases), input AS (SELECT *, jsonb_build_object('title','GitHub fix #471','id',id,'requester',requester,'idempotencyKey',idempotency_key,'status',status,'version',version,'leaseOwner',lease_owner,'leaseExpiresAt',lease_expires_at,'dispatcher',jsonb_build_object('phase',phase,'attempts',1,'base',repeat('b',40),'recipeId','recipe-1','grantId','grant-1')) AS payload, CASE WHEN grant_present THEN jsonb_build_object('base',repeat('b',40),'recipeId',CASE WHEN wrong_recipe THEN 'other' ELSE 'recipe-1' END,'delegationId','grant-1','contextId',id,'repository','GLORIFIER7/GLORIFIER','delegator','github:32674233','principal','digital-me','expiresAt',statement_timestamp()+interval '10 minutes') END AS grant_envelope FROM seeds) SELECT name,expected,coalesce(((requester = 'github:32674233'::text) AND (id ~ '^mission-coding-[a-f0-9]{64}$'::text) AND (idempotency_key ~ '^github:GLORIFIER7/GLORIFIER:comment:[1-9][0-9]{0,15}$'::text) AND ((payload ->> 'title'::text) = 'GitHub fix #471'::text) AND ((payload ->> 'id'::text) = id) AND ((payload ->> 'requester'::text) = requester) AND ((payload ->> 'idempotencyKey'::text) = idempotency_key) AND ((payload ->> 'status'::text) = status) AND ((payload ->> 'version'::text) = (version)::text) AND (status = ANY (ARRAY['blocked'::text, 'failed'::text, 'completed'::text, 'reconciliation-required'::text]))),false) AS old_result,coalesce(((requester = 'github:32674233'::text) AND (id ~ '^mission-coding-[a-f0-9]{64}$'::text) AND (idempotency_key ~ '^github:GLORIFIER7/GLORIFIER:comment:[1-9][0-9]{0,15}$'::text) AND ((payload ->> 'title'::text) = 'GitHub fix #471'::text) AND ((payload ->> 'id'::text) = id) AND ((payload ->> 'requester'::text) = requester) AND ((payload ->> 'idempotencyKey'::text) = idempotency_key) AND ((payload ->> 'status'::text) = status) AND ((payload ->> 'version'::text) = (version)::text) AND ((status = ANY (ARRAY['blocked'::text, 'failed'::text, 'completed'::text, 'reconciliation-required'::text])) OR (status = 'executing' AND lease_owner ~ '^[a-zA-Z0-9][a-zA-Z0-9_-]{0,127}$' AND lease_expires_at > statement_timestamp() AND lease_expires_at <= statement_timestamp() + interval '305 seconds' AND payload->>'leaseOwner' = lease_owner AND (payload->>'leaseExpiresAt')::timestamptz = lease_expires_at AND payload->'dispatcher'->>'phase' IN ('preparing','publishing') AND payload->'dispatcher'->>'attempts' IN ('1','2') AND payload->'dispatcher'->>'base' ~ '^[a-f0-9]{40}$' AND grant_envelope->>'base' = payload->'dispatcher'->>'base' AND grant_envelope->>'recipeId' = payload->'dispatcher'->>'recipeId' AND grant_envelope->>'delegationId' = payload->'dispatcher'->>'grantId' AND grant_envelope->>'contextId' = id AND grant_envelope->>'repository' = 'GLORIFIER7/GLORIFIER' AND grant_envelope->>'delegator' = requester AND grant_envelope->>'principal' = 'digital-me' AND (grant_envelope->>'expiresAt')::timestamptz > statement_timestamp()))),false) AS new_result FROM input;
